async function loadChunkedData(){
 const configResponse=await fetch('./city-config.json').catch(()=>null),config=configResponse?.ok?await configResponse.json().catch(()=>null):null;if(typeof config?.base==='string')cityBaseURL=new URL(config.base,location.href);
 const cityResponse=await fetch(new URL('manifest.json',cityBaseURL)).catch(()=>null);
 const cityCandidate=cityResponse?.ok?parseCityManifest(await cityResponse.text().catch(()=>'')):null;
 if(cityCandidate){cityManifest=cityCandidate;cityManifest.edges=cityManifest.network.edgeCount;return [cityManifest,{nodes:[],edges:[]},{buildings:[],trees:[]}];}
 const response=await fetch('./data/manifest.json');if(!response.ok)throw Error('manifest');const manifest=await response.json();
 const load=async files=>(await Promise.all(files.map(async file=>{const r=await fetch('./data/'+file);if(!r.ok)throw Error(file);return r.json();}))).flat();
 const [metaResponse,nodes,edges,buildings,trees]=await Promise.all([fetch('./data/'+manifest.meta),load(manifest.nodes),load(manifest.edges),load(manifest.buildings),load(manifest.trees)]);
 if(!metaResponse.ok)throw Error(manifest.meta);return [await metaResponse.json(),{nodes,edges},{buildings,trees}];
}
function berlinParts(d){return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).map(x=>[x.type,x.value]));}
function dateNow(){const p=berlinParts(new Date());return `${p.year}-${p.month}-${p.day}`;}
function selectedISO(){const day=$('date').value,mins=+$('time').value;let ms=Date.parse(day+'T00:00:00Z')+mins*60000;
 // Resolve a Berlin wall clock against the actual IANA DST offset.
 for(let i=0;i<3;i++){const p=berlinParts(new Date(ms)),asUTC=Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:00Z`),target=Date.parse(day+'T00:00:00Z')+mins*60000;const change=target-asUTC;ms+=change;if(!change)break;}return new Date(ms).toISOString();}
function aboutContent(){return lang==='de'?`<p><strong>Sonnenpfad</strong> wurde von <strong>Mohammadreza Bakhshi</strong> entwickelt und nutzt Daten des Fußgängeratlas Stuttgart.</p><ul><li><strong>Gebiet:</strong> ${cityManifest?'Stadtgebiet Stuttgart':'Zentrum Stuttgart'}. ${meta?meta.edges.toLocaleString('de-DE'):'–'} Teilkanten aus dem bereinigten Netz; Datensatz vom 15.09.2026.</li><li><strong>Themen:</strong> Steigung, Oberfläche, Sommer-/Winterschatten, UTCI, Lärm und relative Windexposition stammen aus dem Atlas. UTCI und Wind sind modellierte Indikatoren, keine Live-Messwerte.</li><li><strong>3D-Gelände:</strong> aus den DEM-basierten Höhenwerten des Wegenetzes interpoliert. Gebäude und Bäume werden zoomabhängig begrenzt, um Qualität und Leistung auszubalancieren.</li><li><strong>Schatten:</strong> Sonnenstand, Gebäudehöhen und vereinfachte Baumkronen. Die Berechnung nimmt eine horizontale Bodenfläche an; Geländeverschattung, Fassadenrückstrahlung und Wolken werden nicht modelliert.</li><li><strong>Wege:</strong> Punkte werden automatisch mit einer nahegelegenen, gemeinsam erreichbaren Komponente des Fußwegenetzes verbunden. Kurze Anschlusslinien zählen nicht zur Weglänge.</li><li><strong>Datenschutz:</strong> Die Routenberechnung erfolgt im Browser. Geteilte Links enthalten gewählte Koordinaten und Karteneinstellungen.</li></ul><p>Live-Wetterdaten sind in dieser Vorschau nicht enthalten.</p><p>Grundkarte: <a href="https://openfreemap.org/" target="_blank" rel="noreferrer">OpenFreeMap</a> / OpenMapTiles / <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors</a>.</p>`:`<p><strong>Sonnenpfad</strong> was developed by <strong>Mohammadreza Bakhshi</strong> and uses data from the Stuttgart Pedestrian Atlas.</p><ul><li><strong>Coverage:</strong> ${cityManifest?'Stuttgart city area':'central Stuttgart'}. ${meta?meta.edges.toLocaleString('en-GB'):'–'} subedges from the cleaned network, dataset dated 15 September 2026.</li><li><strong>Themes:</strong> slope, surface, summer/winter shade, UTCI, noise and relative wind exposure come from the atlas. UTCI and wind are modelled indicators, not live measurements.</li><li><strong>3D terrain:</strong> interpolated from DEM-derived walking-network elevations. Buildings and trees use zoom-dependent limits to balance quality and performance.</li><li><strong>Shade:</strong> solar position, building heights and simplified tree crowns. The calculation assumes flat ground and does not include terrain occlusion, clouds or reflected radiation.</li><li><strong>Routes:</strong> points connect to a nearby mutually reachable component. Short access lines are excluded from route length.</li><li><strong>Privacy:</strong> Routes are calculated in the browser. Shared links contain selected coordinates and map settings.</li></ul><p>Live weather is not included in this preview.</p><p>Basemap: <a href="https://openfreemap.org/" target="_blank" rel="noreferrer">OpenFreeMap</a> / OpenMapTiles / <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors</a>.</p>`;}
function language(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>el.textContent=t(el.dataset.i));$('language').textContent=lang==='de'?'EN':'DE';$('language').setAttribute('aria-label',lang==='de'?'Switch to English':'Auf Deutsch wechseln');$('about-content').innerHTML=aboutContent();status(statusKey);for(const [id,k]of [['swap','swap'],['pick-origin','pickOrigin'],['pick-destination','pickDestination'],['locate','locate'],['fit','fit'],['close-about','close']]){$(id).setAttribute('aria-label',t(k));$(id).title=t(k);}document.querySelectorAll('[data-profile],[data-slope]').forEach(button=>button.title=button.querySelector('[data-i]').textContent);$('origin').setAttribute('aria-label',t('from'));$('destination').setAttribute('aria-label',t('to'));if($('mobility-profile'))$('profile-description').textContent=profileDescriptions[lang][$('mobility-profile').value]||'';updateStep4Language();if(result)showResult();updateClock();}
