function renderThemeLegend(){const box=$('theme-legend'),definition=THEME_DEFS[activeTheme];if(!box||!definition){if(box)box.hidden=true;return;}box.hidden=false;box.innerHTML=`<strong></strong><div class="legend-items"></div><div class="legend-zoom" hidden></div>`;box.querySelector('strong').textContent=definition[lang];const items=box.querySelector('.legend-items');for(const [color,label] of definition.legend){const item=document.createElement('span');item.className='legend-item';item.innerHTML='<i class="legend-line"></i><span></span>';item.querySelector('i').style.background=color;item.querySelector('span').textContent=label;items.append(item);}const note=box.querySelector('.legend-zoom');note.textContent=t('layersZoom');note.hidden=!map||map.getZoom()>=14.5;}
function applyTheme(){if(map?.getLayer('network-line')){const definition=THEME_DEFS[activeTheme];map.setPaintProperty('network-line','line-color',definition?definition.expression:'#b6c2c7');map.setPaintProperty('network-line','line-width',definition?['interpolate',['linear'],['zoom'],14.5,2.2,17,4.2]:['interpolate',['linear'],['zoom'],13,.7,17,2.5]);map.setPaintProperty('network-line','line-opacity',definition ? .85 : .65);}renderThemeLegend();}
