function updateStep4Language(){if(!$('theme'))return;const options=$('theme').options;options[0].textContent=t('themeNone');[...options].slice(1).forEach(option=>{option.textContent=THEME_DEFS[option.value]?.[lang]||option.textContent;});for(const label of document.querySelectorAll('.poi-toggle')){const definition=POI_DEFS.find(item=>item.k===+label.dataset.kind);if(definition)label.querySelector('.poi-name').textContent=definition[lang];}const layersToggle=$('layers-toggle'),layersTitle=t('layersTitle');layersToggle.title=layersTitle;layersToggle.setAttribute('aria-label',layersTitle);renderThemeLegend();}
function setupStep4Controls(){const holder=$('poi-options');for(const definition of POI_DEFS){const label=document.createElement('label');label.className='poi-toggle';label.dataset.kind=definition.k;label.style.setProperty('--poi-color',definition.color);label.innerHTML=`<input type="checkbox" value="${definition.k}"><span class="poi-dot"></span><span class="poi-name"></span>`;const input=label.querySelector('input');input.checked=selectedPois.has(definition.k);input.onchange=event=>{event.target.checked?selectedPois.add(definition.k):selectedPois.delete(definition.k);applyPoiFilter();};holder.append(label);}$('theme').value=activeTheme;$('theme').onchange=()=>{activeTheme=$('theme').value;applyTheme();};const close=()=>{$('layers-panel').hidden=true;$('layers-toggle').setAttribute('aria-expanded','false');};$('layers-toggle').onclick=()=>{const opening=$('layers-panel').hidden;$('layers-panel').hidden=!opening;$('layers-toggle').setAttribute('aria-expanded',String(opening));};$('layers-close').onclick=close;updateStep4Language();}
function updateSunDirection(){const el=$('sun-direction');if(!el||!currentSun)return;const angle=currentSun.azimuth-(map?.getBearing()||0);el.style.setProperty('--sun-angle',`${angle}deg`);el.style.setProperty('--ray-angle',`${angle+180}deg`);el.classList.toggle('is-night',currentSun.altitude<=0);el.setAttribute('aria-label',lang==='de'?`Sonne: ${Math.round(currentSun.altitude)} Grad Höhe, ${Math.round(currentSun.azimuth)} Grad Azimut`:`Sun: ${Math.round(currentSun.altitude)} degrees elevation, ${Math.round(currentSun.azimuth)} degrees azimuth`);}
function updateClock(){const v=+$('time').value;$('clock').textContent=String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0');if(currentSun)$('sun-elevation').textContent=currentSun.altitude<=0?t('night'):currentSun.altitude<=2?t('lowSun'):`☀ ${Math.round(currentSun.altitude)}° · ${t('sunHeight')}`;updateSunDirection();}
function placeLabel(feature){const p=feature.properties||{},name=p.name||p.street||p.city||t('point'),context=[p.street&&p.street!==name?p.street:null,p.housenumber,p.postcode,p.city].filter(Boolean).join(' ');return {name,context};}
function showSearchResults(i,features,message=''){const box=$(i?'destination-results':'origin-results');box.replaceChildren();if(message){const item=document.createElement('div');item.className='search-empty';item.textContent=message;box.append(item);}for(const featureItem of features){const coordinates=featureItem.geometry?.coordinates;if(!Array.isArray(coordinates)||coordinates.length<2)continue;const label=placeLabel(featureItem),button=document.createElement('button');button.type='button';button.className='search-result';button.setAttribute('role','option');button.innerHTML=`<strong></strong><span></span>`;button.querySelector('strong').textContent=label.name;button.querySelector('span').textContent=label.context;button.onclick=()=>{setCustom(i,[coordinates[0],coordinates[1]],[label.name,label.context].filter(Boolean).join(', '));box.hidden=true;map?.flyTo({center:coordinates,zoom:15});};box.append(button);}box.hidden=!box.childElementCount;}
async function searchPlaces(i,query){const normalized=query.trim();if(normalized.length<3){showSearchResults(i,[]);return;}const key=`${lang}:${normalized.toLowerCase()}`;if(searchCache.has(key)){showSearchResults(i,searchCache.get(key));return;}try{const url=new URL('https://photon.komoot.io/api/');url.search=new URLSearchParams({q:normalized,limit:'6',lang,bbox:'9.03,48.69,9.32,48.87',lon:String(map?.getCenter().lng||9.18),lat:String(map?.getCenter().lat||48.777)});const response=await fetch(url,{headers:{Accept:'application/json'}});if(!response.ok)throw Error('search');const data=await response.json(),features=(data.features||[]).filter(item=>item.geometry?.type==='Point');searchCache.set(key,features);if($(i?'destination':'origin').value.trim()===normalized)showSearchResults(i,features,features.length?'':t('searchNone'));}catch{if($(i?'destination':'origin').value.trim()===normalized)showSearchResults(i,[],t('searchFail'));}}
function populate(){for(const [i,id]of ['origin','destination'].entries()){const input=$(id);input.value='';let timer;input.oninput=()=>{clearTimeout(timer);points[i]=null;markers[i]?.remove();markers[i]=null;invalidateRoute();if(input.value.trim().length>=3)timer=setTimeout(()=>searchPlaces(i,input.value),350);else showSearchResults(i,[]);};input.onfocus=()=>{if(input.value.trim().length>=3)searchPlaces(i,input.value);};input.onkeydown=e=>{if(e.key==='Escape')$(i?'destination-results':'origin-results').hidden=true;};}}
function setCustom(i,p,label){points[i]=p;const input=$(i?'destination':'origin');input.value=label||`${t('point')} · ${p[1].toFixed(4)}, ${p[0].toFixed(4)}`;updateMarkers();invalidateRoute();if(innerWidth<=800){$('sidebar-body').classList.remove('expanded');$('panel-toggle').setAttribute('aria-expanded','false');}}
