function setPreference(p){preference=p;document.querySelectorAll('[data-pref]').forEach(b=>{b.classList.toggle('selected',b.dataset.pref===p);b.setAttribute('aria-pressed',String(b.dataset.pref===p));});if(result)calculate();}
