function routeOptions(){const selectedProfile=$('mobility-profile').value,mobilityProfile=selectedProfile==='none'?'standard':selectedProfile,options={preference:currentSun?.altitude<=2?'balanced':preference,mobilityProfile};if(mobilityProfile==='custom')Object.assign(options,{avoidSteps:$('steps').checked,avoidEscalators:$('escalators').checked,slopeMode:$('slope-mode').value});return options;}
function updateProfile(){const profile=$('mobility-profile').value,custom=profile==='custom';$('profile-description').textContent=profileDescriptions[lang][profile]||'';$('advanced-routing').hidden=!custom;$('advanced-routing').open=custom;document.querySelectorAll('[data-profile]').forEach(button=>{const selected=button.dataset.profile===profile;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});if(result)calculate();}
