 if(loadId!==tileLoadId)return;while(cityTileCache.size>40){const old=[...cityTileCache.keys()].find(key=>!keys.includes(key));if(!old)break;cityTileCache.delete(old);}
 const nextKeys=keys.join(','),selected=keys.map(key=>cityTileCache.get(key)).filter(Boolean);activeTileKeys=nextKeys;updateVisibleCitySources(selected);renderThemeLegend();
