function renderProfile(){const box=$('elevation-profile'),values=result?.profile?.filter(p=>p.every(Number.isFinite));if(!box||!values||values.length<2){if(box)box.hidden=true;return;}box.hidden=false;const w=300,h=86,bottom=10,zs=values.map(p=>p[1]),min=Math.min(...zs),max=Math.max(...zs),range=Math.max(8,max-min),low=(min+max-range)/2,high=low+range,total=values.at(-1)[0]||1;const pts=values.map(([d,z])=>[d/total*w,6+(high-z)/(high-low)*(h-16)]),line=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' '),area=line+` L ${w} ${h-bottom} L 0 ${h-bottom} Z`;$('elevation-line').setAttribute('d',line);$('elevation-area').setAttribute('d',area);$('elevation-range').textContent=`${Math.round(min)}–${Math.round(max)} m`;$('elevation-start').textContent=`A · ${Math.round(values[0][1])} m`;$('elevation-end').textContent=`B · ${Math.round(values.at(-1)[1])} m`;}
const showResultBase=showResult;showResult=()=>{showResultBase();if(result&&!result.error){$('snap-note').textContent=lang==='de'?`Automatischer Netzanschluss: Start ${Math.round(result.snapDistances[0])} m, Ziel ${Math.round(result.snapDistances[1])} m. Die Anschlusslinien zählen nicht zur Route.`:`Automatic network connection: start ${Math.round(result.snapDistances[0])} m, destination ${Math.round(result.snapDistances[1])} m. Access lines are not counted in the route.`;renderProfile();}};
function circlePolygon(center,r,steps=12){const ring=[];for(let i=0;i<=steps;i++){const a=i*Math.PI*2/steps;ring.push(ll([center[0]+r*Math.cos(a),center[1]+r*Math.sin(a)]));}return [ring];}
function treeDimensions(tree){return {r:tree.dr??(tree.h>=15?tree.r*.8:tree.r),h:tree.dh??(tree.h>=15?tree.h*.8:tree.h)};}
function treeFlatFeatures(trees){return trees.map(tree=>{const {r,h}=treeDimensions(tree);return feature('Polygon',circlePolygon(tree.p,r,24),{height:h});});}
function treePartsFor(trees,slices=6,segments=12){const parts=[];for(const tree of trees){const {r,h}=treeDimensions(tree),center=Math.max(r+.5,h-r),bottom=Math.max(.2,center-r);parts.push(feature('Polygon',circlePolygon(tree.p,Math.max(.18,Math.min(.38,r*.16)),8),{base:0,height:Math.max(.8,bottom+.3),color:'#6b4d32'}));for(let i=0;i<slices;i++){const base=bottom+2*r*i/slices,top=bottom+2*r*(i+1)/slices,mid=(base+top)/2,radius=Math.max(.25,Math.sqrt(Math.max(0,r*r-(mid-center)*(mid-center))));parts.push(feature('Polygon',circlePolygon(tree.p,radius,segments),{base,height:top,color:tree.evergreen?'#2f6d4a':i<slices/2?'#4f8d5d':'#5f9b68'}));}}return parts;}
function addV7Layers(){map.setPaintProperty('shade-fill','raster-opacity',.55);map.addSource('osm-raster',{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,maxzoom:19,attribution:'© OpenStreetMap contributors'});map.addLayer({id:'osm-raster',type:'raster',source:'osm-raster',layout:{visibility:'none'}},'network-line');map.addSource('topo-raster',{type:'raster',tiles:['https://tile.opentopomap.org/{z}/{x}/{y}.png'],tileSize:256,maxzoom:17,attribution:'© OpenStreetMap contributors · SRTM · OpenTopoMap'});map.addLayer({id:'topo-raster',type:'raster',source:'topo-raster',layout:{visibility:'none'}},'network-line');const terrainTiles=[new URL('./dem/',location.href).href+'{z}/{x}/{y}.png'],terrainSource={type:'raster-dem',tiles:terrainTiles,tileSize:256,minzoom:12,maxzoom:14,bounds:meta.bounds,encoding:'mapbox',attribution:'Terrain: Fußgängeratlas Stuttgart'};map.addSource('terrain-dem',terrainSource);map.addSource('terrain-hillshade',{...terrainSource});map.addLayer({id:'terrain-hillshade',type:'hillshade',source:'terrain-hillshade',layout:{visibility:'none'},paint:{'hillshade-exaggeration':.38,'hillshade-shadow-color':'#26384f','hillshade-highlight-color':'#f5cf62','hillshade-accent-color':'#70808d'}},'network-line');const treeParts=[];for(const tree of obstacles.trees){const tr=tree.dr??(tree.h>=15?tree.r*.8:tree.r),th=tree.dh??(tree.h>=15?tree.h*.8:tree.h),crownCenter=Math.max(tr+.5,th-tr),bottom=Math.max(.2,crownCenter-tr),slices=6;treeParts.push(feature('Polygon',circlePolygon(tree.p,Math.max(.18,Math.min(.38,tr*.16)),10),{base:0,height:Math.max(.8,bottom+.3),color:'#6b4d32'}));for(let i=0;i<slices;i++){const base=bottom+2*tr*i/slices,top=bottom+2*tr*(i+1)/slices,mid=(base+top)/2,radius=Math.max(.25,Math.sqrt(Math.max(0,tr*tr-(mid-crownCenter)*(mid-crownCenter))));treeParts.push(feature('Polygon',circlePolygon(tree.p,radius,12),{base,height:top,color:tree.evergreen?'#2f6d4a':i<3?'#4f8d5d':'#5f9b68'}));}}map.addSource('trees-3d',{type:'geojson',data:fc(treeParts)});map.addLayer({id:'trees-3d',type:'fill-extrusion',source:'trees-3d',layout:{visibility:'none'},paint:{'fill-extrusion-color':['get','color'],'fill-extrusion-base':['get','base'],'fill-extrusion-height':['get','height'],'fill-extrusion-opacity':.94,'fill-extrusion-vertical-gradient':true}});map.addSource('access',{type:'geojson',data:fc([])});map.addLayer({id:'access-line',type:'line',source:'access',layout:{'line-cap':'round'},paint:{'line-color':'#f4c542','line-width':3,'line-dasharray':[1.2,1.2]}});}
function addStep4Layers(){map.moveLayer('network-line','route-halo');map.addSource('pois',{type:'geojson',data:fc([])});map.addLayer({id:'poi-points',type:'circle',source:'pois',minzoom:14.5,paint:{'circle-color':['match',['get','k'],...POI_DEFS.flatMap(item=>[item.k,item.color]),'#687c8c'],'circle-radius':['interpolate',['linear'],['zoom'],14.5,3.5,17,6.5],'circle-stroke-color':'#fff','circle-stroke-width':1.4,'circle-opacity':.92}});applyTheme();applyPoiFilter();map.on('mouseenter','poi-points',()=>{if(pick===null)map.getCanvas().style.cursor='pointer';});map.on('mouseleave','poi-points',()=>{if(pick===null)map.getCanvas().style.cursor='';});map.on('click','poi-points',event=>{if(pick!==null)return;const item=event.features?.[0],kind=POI_DEFS.find(definition=>definition.k===item?.properties?.k);if(!item||!kind)return;const content=document.createElement('div'),title=document.createElement('strong'),detail=document.createElement('div');title.textContent=kind[lang];detail.textContent=item.properties.n||'';content.append(title);if(detail.textContent)content.append(detail);new maplibregl.Popup({closeButton:true,maxWidth:'260px'}).setLngLat(item.geometry.coordinates).setDOMContent(content).addTo(map);});}
const setupLayersBase=setupLayers;setupLayers=()=>{setupLayersBase();addV7Layers();addStep4Layers();};
